// ── Elegir qué publicar ─────────────────────────────────────────────────────
// Entra: feed.json completo. Sale: un item por oferta lista para Telegram.
// Toda la política de publicación vive aquí; se puede editar sin tocar el resto.
//
// Desde octubre de 2026 el feed sale de la VITRINA (src/data/vitrina.json):
// productos que elegiste tú, cada uno con tu link OFICIAL de afiliado. Este
// nodo publica ese link TAL CUAL — el de la etiqueta de Telegram si lo
// generaste (o.enlaces.tg), si no el general (o.enlace). Nunca arma uno.

const CONF = $('Configuracion').first().json;
const feed = $input.first().json;

// El feed declara su forma. Si cambia y este nodo no se enteró, es mejor un
// error ruidoso que mensajes con campos vacíos publicados en tu canal.
if (feed.esquema !== 2) {
  throw new Error('Esquema ' + feed.esquema + ' no reconocido. Revisa generarFeedPublico.js antes de publicar.');
}

const CATEGORIA = String(CONF.categoria || '').trim();   // vacío = todas
const CANAL = CONF.canal_codigo || 'tg';
const SCORE_MIN = Number(CONF.score_minimo) || 0;
const MAX = Number(CONF.max_por_corrida);

// Memoria entre ejecuciones: qué ya se publicó. Sin esto, cada 3 horas se
// repetirían las mismas ofertas y el canal se silencia solo.
const estado = $getWorkflowStaticData('global');
estado.publicados = Array.isArray(estado.publicados) ? estado.publicados : [];
const yaPublicado = new Set(estado.publicados);

const ahora = Date.now();
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mxn = (n) => '$' + Number(n).toLocaleString('es-MX', { maximumFractionDigits: 0 });
const recortar = (s, n) => (s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…');
const linkDe = (o) => (o.enlaces && o.enlaces[CANAL]) || o.enlace;
// Solo los links cortos oficiales del generador. Si algo distinto llegara al
// feed, no se publica: un link editado es un link que no cobra.
const esOficial = (u) => /^https:\/\/(meli\.la\/|(www\.)?mercadolibre\.com(\.mx)?\/sec\/)[A-Za-z0-9_-]{4,}\/?$/.test(String(u || ''));

const candidatos = (feed.items || [])
  .filter((o) => !CATEGORIA || o.categoria === CATEGORIA)
  .filter((o) => o.imagen)                       // sendPhoto necesita imagen
  .filter((o) => esOficial(linkDe(o)))
  .filter((o) => (o.score || 0) >= SCORE_MIN)
  // Una relámpago que ya terminó no se anuncia, aunque el feed sea de hace rato.
  .filter((o) => !o.caduca || Date.parse(o.caduca) > ahora)
  // LA REGLA QUE NO SE NEGOCIA: nivel 'alto' significa que el producto ESTUVO
  // MAS BARATO hace poco, o sea que el descuento es contra un precio inflado.
  // 'descuento-falso' es todavia mas grave: el precio no se movio nada y el
  // vendedor anuncia una rebaja que no existe. Este flujo corre solo, sin
  // nadie mirando -- se excluyen los DOS niveles, no solo 'alto'.
  .filter((o) => !o.historico || (o.historico.nivel !== 'alto' && o.historico.nivel !== 'descuento-falso'))
  .filter((o) => !yaPublicado.has(o.id + '@' + o.revisado))
  // El feed ya viene en el orden de /hoy: relámpago primero, luego destacados.
  .slice(0, MAX);

function armar(o, tituloMax) {
  const l = [];
  l.push((o.relampago ? '⚡ <b>OFERTA RELÁMPAGO</b>\n' : '') + '🔥 <b>' + esc(recortar(o.titulo, tituloMax)) + '</b>');
  l.push('');
  let precio = '💰 <b>' + mxn(o.precio_actual) + '</b>';
  if (o.precio_previo && o.precio_previo > o.precio_actual) {
    precio += '  <s>' + mxn(o.precio_previo) + '</s>';
    if (o.descuento) precio += '  −' + o.descuento + '%';
  }
  l.push(precio);

  const senales = [];
  if (o.rating) senales.push(o.rating + '★');
  if (o.vendidos >= 1000) senales.push('+' + Math.round(o.vendidos / 1000) + ' mil vendidos');
  if (o.envio_gratis) senales.push('envío gratis');
  if (senales.length) l.push('⭐ ' + esc(senales.join(' · ')));

  if (o.termina) {
    const fin = new Date(o.termina).toLocaleString('es-MX', { timeZone: 'America/Mexico_City', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false });
    l.push('⏱ Termina: ' + esc(fin));
  }
  // La frase del historico es el diferenciador; si no hay, tu nota.
  if (o.historico && o.historico.texto) l.push('📉 ' + esc(o.historico.texto));
  else if (o.nota) l.push('📝 ' + esc(o.nota));

  l.push('');
  l.push('👉 ' + linkDe(o));
  l.push('');
  l.push('<i>Enlace de afiliado: si compras, recibo una comisión sin costo extra para ti. Precio visto el ' + esc(new Date(o.revisado).toLocaleDateString('es-MX', { timeZone: 'America/Mexico_City', day: 'numeric', month: 'short' })) + '; confírmalo en Mercado Libre.</i>');
  return l.join('\n');
}

const salida = [];
for (const o of candidatos) {
  // El caption de Telegram tope a 1024 caracteres. Se recorta el TITULO, nunca
  // el aviso de afiliado ni el enlace.
  let mensaje = armar(o, 90);
  for (const max of [70, 50, 35]) {
    if (mensaje.length <= 1024) break;
    mensaje = armar(o, max);
  }
  // La tarjeta 4:5 del sitio (con precio y Sello K-P) se ve mejor que la foto
  // pelada; si no existiera, Telegram rechazaría la URL, así que se usa la de ML.
  salida.push({ json: { id: o.id, titulo: o.titulo, imagen: feed.sitio + '/promos/' + o.id + '.jpg', imagen_ml: o.imagen, mensaje: mensaje } });
}

// Recordar lo publicado (id + fecha de revisión: si actualizas el precio, se
// puede volver a anunciar), podado a 500 para que el estado no crezca sin techo.
estado.publicados = candidatos.map((o) => o.id + '@' + o.revisado).concat(estado.publicados).slice(0, 500);

return salida;
